using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MeissasSaiphGiftOmenData", menuName = "Data/Battle/Omens System/Omen Data/Event/MeissasSaiphGift Omen Data")]
public class MeissasSaiphGiftOmenData : OmenData
{
	[Header("MeissasSaiphGift")]
	[SerializeField]
	private bool meissaGift;

	public override void Initialize(OmenInstance omenInstance)
	{
		if (meissaGift)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.MeissasGiftDiscountAmount = ActionValue;
		}
		else
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.SaiphsGiftDiscountAmount = ActionValue;
		}
	}

	public override void OmenRemoved()
	{
		if (meissaGift)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.MeissasGiftDiscountAmount = 0;
		}
		else
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.SaiphsGiftDiscountAmount = 0;
		}
	}
}
